	justify-content: center;
	gap: var(--nand-space-2);
	height: var(--nand-control-height);
	padding: 0 var(--nand-space-3);
	border: 1px solid var(--nand-border-color);
	border-radius: var(--nand-radius-sm);
	background: var(--nand-surface);
	box-shadow: none;
	color: var(--text-normal);
	font-size: var(--nand-text-body);
	font-weight: var(--font-medium);
	white-space: nowrap;
	cursor: pointer;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), border-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-btn:hover:not(:disabled) { background: var(--nand-surface-hover); border-color: var(--nand-border-color-strong); }
button.nand-btn:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }
button.nand-btn:disabled { opacity: 0.5; cursor: default; }
button.nand-btn svg { width: var(--nand-icon-size); height: var(--nand-icon-size); flex: none; }
button.nand-btn--sm { height: var(--nand-control-height-sm); padding: 0 var(--nand-space-2); font-size: var(--nand-text-caption); }
button.nand-btn--primary { background: var(--interactive-accent); border-color: transparent; color: var(--text-on-accent); }
button.nand-btn--primary:hover:not(:disabled) { background: var(--interactive-accent-hover); border-color: transparent; }
button.nand-btn--ghost { background: transparent; border-color: transparent; color: var(--text-muted); }
button.nand-btn--ghost:hover:not(:disabled) { background: var(--nand-surface-hover); border-color: transparent; color: var(--text-normal); }
button.nand-btn--danger { color: var(--nand-tone-error); }
button.nand-btn--danger:hover:not(:disabled) { background: color-mix(in srgb, var(--nand-tone-error) 10%, transparent); border-color: color-mix(in srgb, var(--nand-tone-error) 40%, transparent); }

button.nand-icon-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex: none;
	width: var(--nand-control-height);
	height: var(--nand-control-height);
	padding: 0;
	border: none;
	border-radius: var(--nand-radius-sm);
	background: transparent;
	box-shadow: none;
	color: var(--text-muted);
	cursor: pointer;
	transition: background-color var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}
button.nand-icon-btn:hover:not(:disabled) { background: var(--nand-surface-hover); color: var(--text-normal); }
button.nand-icon-btn:focus-visible { box-shadow: var(--nand-focus-ring); outline: none; }
button.nand-icon-btn.is-active,
button.nand-icon-btn[aria-pressed="true"] { background: var(--nand-surface-active); color: var(--text-normal); }
button.nand-icon-btn:disabled { opacity: 0.4; cursor: default; }
button.nand-icon-btn--sm { width: var(--nand-control-height-sm); height: var(--nand-control-height-sm); }
button.nand-icon-btn svg { width: var(--nand-icon-size); height: var(--nand-icon-size); }

/* ----- Text fields ----- */
.nand-field {
	display: flex;
