/* ----- User accent overrides (any preset, including Follow system) ----- */
body.nand-theme-accent-light.theme-light,
body.nand-theme-accent-dark.theme-dark {
	--interactive-accent: var(--nand-user-accent);
	--interactive-accent-hover: color-mix(in srgb, var(--nand-user-accent) 86%, var(--text-normal));
	--color-accent: var(--nand-user-accent);
	--text-accent: var(--nand-user-accent);
	--text-accent-hover: color-mix(in srgb, var(--nand-user-accent) 80%, var(--text-normal));
	--link-color: var(--nand-user-accent);
	--background-modifier-border-focus: var(--nand-user-accent);
}
body.nand-theme-accent-light.theme-light { --nand-user-accent: var(--nand-user-accent-light); }
body.nand-theme-accent-dark.theme-dark { --nand-user-accent: var(--nand-user-accent-dark); }
body.nand-theme-line-height {
	--line-height-normal: var(--nand-user-line-height);
}
/* =================================================================
   Markdown structure: headings and emphasis read differently at a glance.
   Applies to Reading view (.markdown-rendered), Live Preview and Source
   mode (.HyperMD-header-N / .cm-header-N, .cm-strong). Driven by Obsidian's
   heading and emphasis variables wherever they exist.
   ================================================================= */

/* ----- Accented headings: H1 rule, H2 accent bar, H3 accent tint ----- */
body.nand-md-headings--accented {
	--h1-size: 1.75em;
	--h1-weight: 700;
	--h1-line-height: 1.25;
	--h2-size: 1.45em;
	--h2-weight: 650;
	--h3-size: 1.22em;
	--h3-weight: 650;
	--h3-color: var(--text-accent);
	--h4-size: 1.08em;
	--h4-weight: 650;
	--h5-size: 1em;
	--h5-weight: 650;
	--h5-color: var(--text-muted);
	--h6-size: 0.94em;
	--h6-weight: 650;
	--h6-color: var(--text-muted);
}
body.nand-md-headings--accented .markdown-rendered h1,
body.nand-md-headings--accented .markdown-source-view .HyperMD-header-1 {
	padding-bottom: 0.3em;
	border-bottom: 2px solid color-mix(in srgb, var(--interactive-accent) 45%, transparent);
}
body.nand-md-headings--accented .markdown-rendered h2,
body.nand-md-headings--accented .markdown-source-view .HyperMD-header-2 {
	padding-inline-start: 0.6em;
	border-inline-start: 4px solid var(--interactive-accent);
}
body.nand-md-headings--accented .markdown-rendered h3,
body.nand-md-headings--accented .markdown-source-view .cm-header-3 {
	letter-spacing: 0.01em;
}
body.nand-md-headings--accented .markdown-rendered h6,
body.nand-md-headings--accented .markdown-source-view .cm-header-6 {
	text-transform: uppercase;
	letter-spacing: 0.06em;
}

/* ----- Emphasis ----- */
body.nand-md-emphasis--accent {
	--bold-weight: 700;
	--bold-color: var(--text-accent);
	--italic-color: var(--text-muted);
}
body.nand-md-emphasis--highlight {
	--bold-weight: 700;
	--italic-color: var(--text-muted);
}
body.nand-md-emphasis--highlight .markdown-rendered strong,
body.nand-md-emphasis--highlight .markdown-source-view .cm-strong {
	background: linear-gradient(transparent 58%, color-mix(in srgb, var(--interactive-accent) 26%, transparent) 58%);
	border-radius: 2px;
}

/* ----- Blockquotes and inline code follow the active accent in any enhanced style ----- */
body.nand-md-headings--accented .markdown-rendered blockquote {
	background: color-mix(in srgb, var(--interactive-accent) 6%, transparent);
	border-radius: 0 var(--radius-s) var(--radius-s) 0;
}
/* ===== Shared: transparent sections for neon, volt, magma, onyx, mono ===== */

/* Tighter kanban gap for neon, volt, magma, onyx */

/* =================================================================
   COMPONENT STYLES
   ================================================================= */

/* Reset Obsidian view-content padding for dashboard */
.workspace-leaf-content[data-type="nand-dashboard-view"] .view-content {
	padding: 0 !important;
}

/* ===== Board tokens =====
   The board's semantic aliases, defined once from the global NAND tokens and Obsidian variables so
   the board follows Obsidian, community themes and NAND theme presets. Board appearance options
   (background image, glass, radius, surface opacity, font scale) override them inline on the root. */
body {
	--db-bg: var(--background-primary);
	--db-bg-secondary: var(--background-secondary);
	--db-bg-section: transparent;
	--db-bg-card: var(--background-primary);
	--db-bg-card-hover: var(--nand-surface-hover);
	--db-bg-sidebar: transparent;
	--db-bg-input: var(--background-modifier-form-field);
	--db-bg-btn: var(--nand-accent-softer);
	--db-bg-btn-hover: var(--nand-accent-soft);
	--db-bg-banner: var(--background-secondary);
	--db-bg-overlay: linear-gradient(135deg, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.25) 100%);
	--db-bg-hover: var(--nand-surface-hover);
	--db-bg-hover-strong: var(--nand-surface-active);
	--db-bg-add-section: var(--background-secondary);
	--db-bg-drop-indicator: var(--nand-accent-softer);
	--db-bg-modal: var(--background-primary);
	--db-bg-modal-raised: var(--background-secondary);

	--db-border: var(--nand-border-color);
	--db-border-card: var(--nand-border-color);
	--db-border-section: transparent;
	--db-border-sidebar: transparent;
	--db-border-input: var(--nand-border-color);
	--db-border-input-focus: var(--interactive-accent);
	--db-border-btn: var(--nand-accent-border);
	--db-border-btn-hover: var(--interactive-accent);
	--db-border-add-section: var(--nand-border-color-strong);
	--db-border-accent: var(--nand-accent-border);

	--db-text: var(--text-normal);
	--db-text-primary: var(--text-normal);
	--db-text-secondary: var(--text-muted);
	--db-text-muted: var(--text-muted);
	--db-text-faint: var(--text-faint);
	--db-text-inverse: #ffffff;
	--db-text-inverse-muted: rgba(255, 255, 255, 0.6);

	--db-accent: var(--interactive-accent);
	--db-accent-light: var(--interactive-accent-hover);
	--db-accent-dim: var(--nand-accent-soft);
	--db-card-accent: var(--interactive-accent);
	--db-danger: var(--nand-tone-error);
	--db-prio-high: var(--nand-tone-error);
	--db-prio-medium: var(--nand-tone-warning);
	--db-prio-low: var(--nand-tone-info);

	--db-shadow-card: var(--nand-shadow-xs);
	--db-shadow-card-hover: var(--nand-shadow-sm);
	--db-backdrop-blur: none;
	--db-radius-sm: var(--nand-radius-sm);
	--db-radius-md: var(--nand-radius-md);
	--db-radius-lg: var(--nand-radius-lg);
	--db-font: var(--font-interface);

	--db-progress-from: var(--interactive-accent);
	--db-progress-to: var(--interactive-accent-hover);
	--db-checkbox: var(--interactive-accent);
	--db-quote-border: var(--blockquote-border-color, var(--interactive-accent));
	--db-link: var(--link-color, var(--text-accent));
	--db-sec-hue: var(--interactive-accent);
	--db-sec-glow: var(--nand-accent-soft);
	--db-aurora-bg: var(--db-bg);
	--db-aurora-size: 100% 100%;
	--db-aurora-speed: 0s;
	--db-pomodoro-text: var(--text-normal);
	--db-pomodoro-running-text: var(--text-on-accent);
}

/* ===== Root ===== */
.nand-dashboard-root {
	--db-text-on-accent: var(--db-text-inverse, var(--text-on-accent));
	--db-text-on-danger: #fff;
	--db-text-on-muted: #fff;
	--db-photo-text: rgba(255, 255, 255, 0.96);
	--db-banner-scrim: linear-gradient(180deg, rgba(0, 0, 0, 0.62), rgba(0, 0, 0, 0.72));
	/* Resolve before a photo widget overrides its foreground tokens. */
	--db-control-bg: var(--db-bg-modal, var(--db-bg-card));
	--db-control-text: var(--db-text);
	display: flex;
	flex-direction: column;
	height: 100%;
	overflow: hidden;
	position: relative;
	isolation: isolate;
	background: var(--db-bg);
	color: var(--db-text);
	font-family: var(--db-font);
	transition: background 0.3s ease, color 0.3s ease;
}

/* ===== User background-image layer (Appearance Studio) =====
   Painted directly on the root, behind all content. Glass surfaces
   (backdrop-filter: var(--db-backdrop-blur)) auto-frost over it. */
.nand-dashboard-bg {
	position: absolute;
	inset: 0;
	z-index: 0;
	pointer-events: none;
	background-position: center;
	background-repeat: no-repeat;
}
.nand-dashboard-bg-scrim {
	position: absolute;
	inset: 0;
}
/* Lift dashboard content above the background layer.
   Banner sits one level above main so its collapsed bookmark tab — which pokes
   downward past the 4px collapsed banner into main's area — stays clickable. */
.nand-dashboard-root > .dashboard-banner {
	position: relative;
	z-index: 2;
}
.nand-dashboard-root > .dashboard-main,
.nand-dashboard-root > .dashboard-mobile-widget-bar {
	position: relative;
	z-index: 1;
}

/* ===== Settings Footer ===== */
/* Section host in the declarative (1.13+) settings tab: one definition row
 * turned into a plain block container so its many Setting rows stack
 * vertically, matching the pre-1.13 fallback layout. Higher specificity than
 * the stock .setting-item flex rules. */
.setting-item.dashboard-settings-section {
	display: block;
	padding: 0;
	border: none;
}

/* Obsidian's app.css gives every .setting-item's first child a 16px
 * inline-end margin (spacing for the standard info|control row). Our section
 * rows start with full-width blocks — the first card / first setting row —
 * which that margin shrinks by 16px and pushes 16px off the right edge.
 * Neutralize it so the first card (微信读书 / 番茄钟) and the first setting
 * (language dropdown) line up with everything below. */
.setting-item.dashboard-settings-section > *:first-child {
	margin-inline-end: 0;
}

/* Sections on an inactive tab. !important: themes restyle .setting-item with
 * their own display rules, which would resurrect hidden rows. */
.setting-item[data-settings-product].dashboard-settings-page-hidden {
	display: none !important;
}

.dashboard-settings-footer {
	text-align: center;
	padding: var(--size-4-8) 0 var(--size-4-2);
	margin-top: var(--size-4-5);
	font-size: var(--nand-text-caption);
	color: var(--text-faint);
	opacity: 0.6;
	letter-spacing: 0.03em;
	user-select: none;
	pointer-events: none;
}

/* ===== Settings: visual layout picker =====
 * Two miniature board diagrams (side rail vs stacked strip) with a centered
 * radio circle under each. The settings pane has no --db-* theme scope, so
 * every value comes from the NAND tokens (which resolve to Obsidian's own
 * variables).
 *
 * The preview mocks read top-down in three zones — banner bar, widget zone
 * (rail / strip, strong accent tint), main sections (soft tint) — so the two
 * layouts differ at a glance. The preview box is fixed-height with overflow
 * hidden and generous bottom clearance: nothing inside may ever crowd the
 * label row below (the old mock's flex bars could overflow onto it). */
.dashboard-layout-picker {
	display: flex;
	gap: var(--size-4-3);
	margin: var(--size-4-1) 0 var(--size-4-4);
	flex-wrap: wrap;
}

.dashboard-layout-option {
	flex: 1 1 150px;
	min-width: 150px;
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: var(--size-4-2);
	padding: var(--size-4-3);
	box-sizing: border-box;
	background: var(--nand-surface);
	border: var(--nand-border);
	border-radius: var(--nand-radius-md);
	box-shadow: var(--nand-shadow-xs);
	transition: border-color var(--nand-duration) var(--nand-ease), box-shadow var(--nand-duration) var(--nand-ease), background-color var(--nand-duration) var(--nand-ease);
}

.dashboard-layout-option:hover {
	border-color: var(--nand-border-color-strong);
	box-shadow: var(--nand-shadow-sm);
}

.dashboard-layout-option--active,
.dashboard-layout-option--active:hover {
	border-color: var(--nand-accent-border);
	background: var(--nand-accent-softer);
	box-shadow: 0 0 0 1px var(--nand-accent-border);
}

/* Inner radius = card radius (10px) - inset (12px) floors at the row radius. */
.dashboard-layout-preview {
	width: 122px;
	height: 88px;
	box-sizing: border-box;
	padding: 6px;
	display: flex;
	flex-direction: column;
	gap: 5px;
	border-radius: var(--nand-radius-sm);
	overflow: hidden;
	flex: 0 0 auto;
	background: color-mix(in srgb, var(--nand-accent) 5%, var(--nand-surface-muted));
}

/* Zone 1: the banner bar spanning the full mock width. */
.dashboard-layout-preview .lp-banner {
	height: 12px;
	flex-shrink: 0;
	border-radius: 3px;
	background: color-mix(in srgb, var(--nand-accent) 32%, transparent);
}

/* Zone 2a (side): body row with the widget rail on the LEFT. */
.dashboard-layout-preview .lp-main {
	flex: 1;
	min-height: 0;
	display: flex;
	gap: 5px;
}

.dashboard-layout-preview .lp-rail {
	width: 26%;
	display: flex;
	flex-direction: column;
	gap: 3px;
}

/* Widget blocks — the strong tint, so the widget zone pops from the sections. */
.dashboard-layout-preview .lp-widget {
	flex: 1;
	min-height: 4px;
	border-radius: 2.5px;
	background: color-mix(in srgb, var(--nand-accent) 42%, transparent);
}

/* Zone 2b (stacked): the widget strip under the banner. */
.dashboard-layout-preview--stacked .lp-strip {
	height: 18px;
	flex-shrink: 0;
	display: flex;
	gap: 3px;
}

.dashboard-layout-preview--stacked .lp-strip .lp-widget {
	flex: 1;
	min-height: 0;
}

/* Zone 3: main sections — the soft tint, stacked as rows. */
.dashboard-layout-preview .lp-board {
	flex: 1;
	min-height: 0;
	display: flex;
	flex-direction: column;
	gap: 3px;
}

.dashboard-layout-preview .lp-board .lp-section {
	flex: 1;
	min-height: 4px;
	border-radius: 2.5px;
	background: color-mix(in srgb, var(--nand-accent) 16%, transparent);
}

.dashboard-layout-option-label {
	font-size: var(--nand-text-body);
	font-weight: 500;
	color: var(--text-muted);
	text-align: center;
}

.dashboard-layout-option--active .dashboard-layout-option-label {
	color: var(--text-normal);
	font-weight: 600;
}

/* The radio circle is THE click target — a real button element, with theme
   button chrome fully reset so no theme can give it a box or a fixed height
   that overflows the card (the failure mode of the old button-bar card). */
.dashboard-layout-radio {
	appearance: none;
	-webkit-appearance: none;
	width: 18px;
	height: 18px;
	box-sizing: border-box;
	border-radius: 50% !important;
	border: 1.5px solid var(--text-muted) !important;
	background: none !important;
	background-color: transparent !important;
	box-shadow: none !important;
	padding: 0 !important;
	margin: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	cursor: pointer;
	transition: border-color var(--nand-duration-fast) var(--nand-ease);
}

.dashboard-layout-radio:hover {
	border-color: var(--nand-accent) !important;
}

.dashboard-layout-radio:focus-visible {
	outline: 2px solid var(--interactive-accent);
	outline-offset: 2px;
}

.dashboard-layout-radio-dot {
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: transparent;
	transition: background-color var(--nand-duration-fast) var(--nand-ease);
}

.dashboard-layout-option--active .dashboard-layout-radio {
	border-color: var(--nand-accent);
}

.dashboard-layout-option--active .dashboard-layout-radio-dot {
	background: var(--nand-accent);
}

/* ===== Settings fallback tab bar (pre-1.13 builds) =====
 * 1.13+ renders the three pages via Obsidian's native navigable definitions;
 * this bar only exists in the display() fallback. */
.dashboard-settings-tabs {
	display: flex;
	flex-wrap: wrap;
	gap: 2px;
	max-width: 100%;
	padding: 2px;
	border-radius: var(--nand-radius-pill);
	background: var(--nand-surface-muted);
	border: var(--nand-border);
	margin-bottom: var(--size-4-4);
}

.dashboard-settings-root {
	display: flex;
	flex-direction: column;
	gap: var(--size-4-3);
	min-width: 0;
}

.dashboard-settings-shell {
	display: flex;
	flex-direction: column;
	gap: var(--size-4-3);
	min-width: 0;
}

/* Product navigation wraps so every module remains visible in narrow settings. */
.dashboard-settings-products {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	white-space: nowrap;
	gap: var(--size-4-1);
	max-width: 100%;
}

.dashboard-settings-content {
	flex: 1 1 auto;
	min-width: 0;
}

.nand-settings {
	display: block;
	min-width: 0;
}

.nand-settings .nand-settings-chrome,
.nand-settings .dashboard-settings-shell {
	display: contents;
}

.nand-settings .dashboard-settings-products {
	grid-column: 1 / -1;
}

.nand-settings > .setting-item.dashboard-settings-section:not(.nand-settings-chrome):not(.dashboard-settings-page-hidden) {
	grid-column: 1 / -1;
	min-width: 0;
}

.dashboard-settings-tab {
	cursor: pointer;
	display: inline-flex;
	align-items: center;
	flex: none;
	gap: 6px;
	min-height: var(--nand-control-height);
	padding: 0 var(--size-4-3);
	border: 1px solid transparent;
	box-shadow: none;
	border-radius: var(--nand-radius-pill);
	background: transparent;
	font-size: var(--nand-text-body);
	font-weight: 500;
	color: var(--text-muted);
	transition: color var(--nand-duration-fast) var(--nand-ease), background-color var(--nand-duration-fast) var(--nand-ease), border-color var(--nand-duration-fast) var(--nand-ease);
}

/* Icon sized to the tab's text so it never dwarfs the label, and vertically
   centered by the flex row above. */
.dashboard-settings-tab-icon {
	display: inline-flex;
	align-items: center;
}

.dashboard-settings-tab-icon svg {
	width: 15px;
	height: 15px;
}

.dashboard-settings-tab:hover {
	color: var(--text-normal);
	background: var(--nand-surface-hover);
}

.dashboard-settings-tab.active {
	background: var(--nand-accent-soft);
	border-color: var(--nand-accent-border);
	color: var(--text-accent);
	font-weight: 600;
}

/* ===== About Author page ===== */
.dashboard-about {
	max-width: 520px;
	margin: 0 auto;
	text-align: center;
	padding: var(--size-4-3) 0 var(--size-4-6);
}

.dashboard-about-intro-line1 {
	font-size: var(--nand-text-title);
	font-weight: 600;
	color: var(--text-normal);
	margin-bottom: var(--size-4-2);
}

.dashboard-about-intro-line {
	font-size: var(--nand-text-body);
	color: var(--text-muted);
	line-height: 1.6;
}

.dashboard-about-divider {
	height: 1px;
	background: var(--nand-border-color);
	margin: var(--size-4-5) auto var(--size-4-2);
	max-width: 320px;
}

.dashboard-about-section {
	margin-top: var(--size-4-5);
}

/* Section headings render as accent-tinted pills — a colored frame that sets
   them apart from the body text below (theme accent, light/dark adaptive). */
.dashboard-about-section-title {
	display: inline-flex;
	align-items: center;
	min-height: 22px;
	font-size: var(--nand-text-caption);
	font-weight: 600;
	letter-spacing: 0.06em;
	padding: 0 var(--size-4-3);
	margin-bottom: var(--size-4-3);
	border-radius: var(--nand-radius-pill);
	color: var(--text-accent);
	background: var(--nand-accent-soft);
	border: 1px solid var(--nand-accent-border);
}

.dashboard-about-project {
	line-height: 1.9;
	font-size: var(--nand-text-body);
}

.dashboard-about-project-name {
	font-weight: 600;
	color: var(--text-normal);
}

.dashboard-about-project-sep {
	color: var(--text-faint);
	margin: 0 6px;
}

.dashboard-about-project-desc {
	color: var(--text-muted);
}

.dashboard-about-follow-name {
	font-size: var(--nand-text-title);
	font-weight: 600;
	color: var(--text-normal);
	margin-bottom: var(--size-4-1);
}

.dashboard-about-follow-platforms {
	font-size: var(--nand-text-caption);
	color: var(--text-muted);
}

.dashboard-about-contact-row {
	line-height: 2;
	font-size: var(--nand-text-body);
}

.dashboard-about-contact-label {
	color: var(--text-muted);
}

.dashboard-about-code {
	font-family: var(--font-monospace);
	background: var(--nand-surface-hover);
	border-radius: var(--nand-radius-xs);
	padding: 1px 6px;
	cursor: pointer;
}

.dashboard-about-code:hover {
	background: var(--nand-surface-active);
}

.dashboard-about-link {
	color: var(--text-accent);
	text-decoration: none;
	border-radius: var(--nand-radius-xs);
}

.dashboard-about-link:hover {
	text-decoration: underline;
}
/* ===== Workspace settings (registry rows) ===== */
/* Standalone divider before the workspace group. NOT a border on the heading
   .setting-item — themes give setting items rounded backgrounds and clip any
   border we draw there; a separate element keeps a straight, square line with
   spacing under our control. */
.dashboard-settings-divider {
	height: 1px;
	background: var(--nand-border-color);
	margin: var(--size-4-5) 0 var(--size-4-3);
}

.dashboard-workspace-row .dashboard-workspace-drag-handle {
	align-self: center;
	display: flex;
	color: var(--text-faint);
	opacity: 0.6;
	cursor: grab;
	border-radius: var(--nand-radius-xs);
	transition: opacity var(--nand-duration-fast) var(--nand-ease), color var(--nand-duration-fast) var(--nand-ease);
}

.dashboard-workspace-row .dashboard-workspace-drag-handle:hover {
	opacity: 1;
	color: var(--text-muted);
}

.dashboard-workspace-row--dragging {
	opacity: 0.45;
}

/* Drop indicators: box-shadow instead of border so native row separators
   and layout are untouched. */
.dashboard-workspace-row--drop-before {
	box-shadow: 0 -2px 0 0 var(--interactive-accent);
}

.dashboard-workspace-row--drop-after {
	box-shadow: 0 2px 0 0 var(--interactive-accent);
}

.dashboard-workspace-path-input {
	width: 160px;
}

/* Aurora gradient animation for aurora theme only */

/* Respect reduced-motion: stop the aurora drift for users who disable animation */

/* Mobile: stop the aurora background drift. The animated background-position
   forces a full-root repaint every frame; on phones (iOS WKWebView in
   particular) this competes with scrolling and janks the whole dashboard.
   Pinning the gradient to the animation's start frame keeps the theme's look
   (the glow band sits exactly where the drift starts); desktop keeps the drift. */

/* Aurora: disable card backdrop-blur.
   The animated gradient root behind translucent cards forces the browser to
   re-blur every frame, which strobes/flickers on many systems. Removing the
   blur eliminates the strobe while keeping the gradient look. */

/* ===== Banner ===== */
.dashboard-banner {
	position: relative;
	height: 120px;
	background-size: cover;
	background-position: center;
	border-radius: var(--db-radius-lg);
	overflow: hidden;
	flex-shrink: 0;
	background-color: var(--db-bg-banner);
	/* Bottom margin keeps the collapsed state's workspace pills (14px tall,
	   hanging from the 4px collapsed bar) clear of the sidebar date below. */
	margin: 0 16px 8px 16px;
}

.dashboard-banner-overlay {
	position: relative;
	min-height: inherit;
	background: var(--db-banner-scrim);
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	/* The switcher owns the top row, even when the quote wraps in a narrow leaf. */
	padding: 40px 48px 24px;
}

.dashboard-banner:not(.dashboard-banner--stats):not(.dashboard-banner--collapsed) {
	height: auto;
	min-height: 120px;
}

.dashboard-banner-content {
	text-align: center;
	position: relative;
	min-width: 0;
	max-width: 100%;
	overflow-wrap: anywhere;
}

.dashboard-banner-quote {
	font-size: 1.2em;
	font-style: italic;
	color: var(--db-photo-text);
	margin: 0 0 8px 0;
	line-height: 1.4;
	border: none;
	padding: 0;
	text-shadow:
		0 1px 3px rgba(0, 0, 0, 0.4),
		0 0 12px rgba(0, 0, 0, 0.15);
}

.dashboard-banner-author {
	font-size: 0.8em;
	color: var(--db-photo-text);
	font-style: normal;
	text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.dashboard-banner-quote--fading,
.dashboard-banner-author--fading {
	opacity: 0;
	transition: opacity 0.4s ease;
}

.dashboard-banner-quote,
.dashboard-banner-author {
	transition: opacity 0.4s ease;
}

.dashboard-banner--fading {
	opacity: 0;
	transition: opacity 0.6s ease;
}

.dashboard-banner {
	transition: opacity var(--nand-duration-slow) var(--nand-ease);
}

.dashboard-banner-edit-btn {
	position: absolute;
	bottom: 8px;
	right: 10px;
	background: none !important;
	border: none !important;
	box-shadow: none !important;
	color: rgba(255, 255, 255, 0.4);
	padding: 2px;
	font-size: 0.55em;
	cursor: pointer;
	opacity: 0;
	transition: opacity 0.2s ease, color 0.2s ease;
	display: flex;
	align-items: center;
	line-height: 1;
	outline: none;
}

.dashboard-banner:hover .dashboard-banner-edit-btn {
	opacity: 1;
	color: rgba(255, 255, 255, 0.8);
}

.dashboard-banner-edit-btn:hover,
.dashboard-banner-edit-btn:active {
	background: none !important;
	border: none !important;
	box-shadow: none !important;
	color: #ffffff !important;
}

/* --- Banner bookmark toggle --- */
.dashboard-banner-pin-btn {
	position: absolute;
	top: 8px;
	right: 10px;
	left: auto;
	z-index: 10;
	background: none !important;
	border: none !important;
	box-shadow: none !important;
	color: rgba(255, 255, 255, 0.4);
	padding: 4px;
	cursor: pointer;
	opacity: 0;
	transition: opacity 0.2s ease, color 0.2s ease, transform 0.2s ease;
	display: flex;
	align-items: center;
	justify-content: center;
	outline: none;
}

.dashboard-banner:hover .dashboard-banner-pin-btn {
	opacity: 1;
	color: rgba(255, 255, 255, 0.8);
}

.dashboard-banner-pin-btn:hover,
.dashboard-banner-pin-btn:active {
	background: none !important;
	border: none !important;
	box-shadow: none !important;
	color: #ffffff !important;
	transform: scale(1.15);
}

/* --- Workspace switcher (banner top-left corner) ---
   Sits in the dead strip ABOVE the stats content: the left stat column's
   hero number starts at y=18 (panel padding 10px + 8px hero offset), so a
   compact 14px-tall pill row at top:2 ends exactly at its top edge — the
   numbers neither move nor get covered. nowrap so a long row extends right
   along the same strip instead of wrapping down over the content.
   Inactive workspaces are faint at rest; the current workspace stays legible. */
.dashboard-workspace-switcher {
	position: absolute;
	top: 2px;
	left: 8px;
	display: flex;
	align-items: center;
	flex-wrap: nowrap;
	gap: 3px;
	padding: 1px 4px;
	z-index: 10;
}

.dashboard-workspace-switcher:hover .dashboard-workspace-btn,
.dashboard-workspace-switcher:focus-within .dashboard-workspace-btn {
	opacity: 1;
}

.dashboard-workspace-btn {
	opacity: 0.25;
	transition: opacity 0.2s ease;
	min-width: 14px;
	height: 14px;
	padding: 0 3px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	background: rgba(0, 0, 0, 0.28);
	border: 1px solid rgba(255, 255, 255, 0.22);
	border-radius: var(--db-radius-sm, 6px);
	color: rgba(255, 255, 255, 0.78);
	font-size: 0.5em;
	line-height: 1;
	cursor: pointer;
	outline: none;
	box-shadow: none !important;
}

.dashboard-workspace-btn:hover,
.dashboard-workspace-btn:active {
	color: #ffffff;
	border-color: rgba(255, 255, 255, 0.5);
	background: rgba(0, 0, 0, 0.4);
}

.dashboard-workspace-btn.active {
	opacity: 1;
	background: var(--db-accent, #6366f1);
	border-color: transparent;
	color: var(--db-text-on-accent, var(--text-on-accent));
}

.dashboard-workspace-add-btn {
	padding: 0;
	width: 14px;
}

.dashboard-banner:not(.dashboard-banner--stats) .dashboard-workspace-btn {
	min-width: var(--nand-control-height);
	width: auto;
	height: var(--nand-control-height);
	font-size: var(--nand-text-caption);
}

.dashboard-workspace-btn:focus-visible {
	outline: 2px solid var(--interactive-accent);
	outline-offset: 2px;
}

.is-mobile .dashboard-banner:not(.dashboard-banner--stats) .dashboard-workspace-btn {
	min-width: var(--nand-touch-target);
	height: var(--nand-touch-target);
}

.is-mobile .dashboard-banner-overlay {
	padding-top: 56px;
}

/* --- Banner collapsed state (desktop only) --- */
@media (min-width: 641px) {
	.dashboard-banner--collapsed {
		height: 4px !important;
		min-height: 0 !important;
		overflow: visible !important;
		background-image: none !important;
		background-color: transparent !important;
	}

	.dashboard-banner--collapsed:not(.dashboard-banner--stats) {
		margin-bottom: 36px;
	}

	.dashboard-banner--collapsed > *:not(.dashboard-banner-pin-btn):not(.dashboard-workspace-switcher):not(.dashboard-sidebar-pin-btn) {
		opacity: 0;
		pointer-events: none;
		visibility: hidden;
		transition: opacity 0.15s ease;
	}

	/* Switcher stays usable on the 4px collapsed bar: pills hang below the
	   edge, mirroring the bookmark tab's re-anchor on the right. Shifted
	   right to clear the sidebar pin, which re-anchors onto the same left
	   edge in this state (pin box spans roughly x 10-29). */
	.dashboard-banner--collapsed .dashboard-workspace-switcher {
		top: 2px;
		left: 36px;
	}

	.dashboard-banner--collapsed .dashboard-workspace-btn:not(.active) {
		opacity: 0.85;
	}

	/* Bookmark tab: anchors at top edge, extends downward. The bottom point
	   is a border-triangle ::after instead of a polygon cut, which the
	   marketplace checker flags as only partially supported on 1.7.4.
	   Half-hidden at rest (fades in on banner hover, full on its own hover)
	   so the collapsed strip stays visually quiet. */
	.dashboard-banner--collapsed .dashboard-banner-pin-btn {
		top: 0;
		left: auto;
		right: 16px;
		width: 28px;
		height: 25px;
		padding: 0;
		opacity: 0.35;
		/* Telescoping: at rest the tab retracts upward over the strip edge
		   (about half its height), like a bookmark slipped back into the book;
		   banner hover lets it extend down naturally. */
		transform: translateY(-13px);
		--dashboard-pin-tail: var(--db-bg-card);
		background: var(--db-bg-card) !important;
		border: none !important;
		border-radius: 4px 4px 6px 6px;
		color: var(--db-text-faint);
		transition: opacity 0.25s ease, color 0.2s ease, transform 0.3s cubic-bezier(0.34, 1.3, 0.64, 1);
	}

	.dashboard-banner--collapsed:hover .dashboard-banner-pin-btn {
		opacity: 0.75;
		transform: translateY(0);
	}

	.dashboard-banner--collapsed .dashboard-banner-pin-btn::after {
		content: '';
		position: absolute;
		left: 50%;
		bottom: -5px;
		width: 0;
		height: 0;
		margin-left: -3px;
		border-left: 3px solid transparent;
		border-right: 3px solid transparent;
		border-top: 5px solid var(--dashboard-pin-tail);
	}

	.dashboard-banner--collapsed .dashboard-banner-pin-btn:hover {
		opacity: 1;
		color: var(--db-text);
		--dashboard-pin-tail: var(--db-bg-hover);
		background: var(--db-bg-hover) !important;
		transform: translateY(0) scaleY(1.06);
	}
}

/* ===== File Suggest Dropdown ===== */
.dashboard-file-suggest {
	background: color-mix(in srgb, var(--db-bg-sidebar) 92%, transparent);
	backdrop-filter: blur(12px);
	-webkit-backdrop-filter: blur(12px);
	border: 1px solid var(--db-border);
	border-radius: var(--db-radius-md);
	box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
	max-height: 240px;
	overflow-y: auto;
	z-index: 200;
}

.dashboard-file-suggest-item {
	display: flex;
	justify-content: space-between;
	align-items: center;
	padding: 6px 10px;
	cursor: pointer;
	font-size: 0.8em;
	gap: 8px;
}

.dashboard-file-suggest-item:hover,
.dashboard-file-suggest-item.active {
	background: var(--db-accent, #6366f1);
}

.dashboard-file-suggest-name {
	color: var(--db-text);
	flex-shrink: 0;
}

.dashboard-file-suggest-item.active .dashboard-file-suggest-name {
	color: white;
}

.dashboard-file-suggest-path {
	color: var(--db-text-faint);
	font-size: 0.85em;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.dashboard-file-suggest-item.active .dashboard-file-suggest-path {
	color: rgba(255, 255, 255, 0.7);
}

/* ===== Wikilink (clickable [[link]]) ===== */
.dashboard-wikilink {
	color: var(--db-accent, #6366f1);
	cursor: pointer;
	text-decoration: none;
	border-bottom: 1px dotted currentColor;
}

.dashboard-wikilink:hover {
	color: var(--db-accent-light, #818cf8);
}

/* ===== External Link (clickable [text](url)) ===== */
.dashboard-external-link {
	color: var(--db-accent, #6366f1);
	cursor: pointer;
	text-decoration: underline;
	text-underline-offset: 2px;
}

.dashboard-external-link:hover {
	color: var(--db-accent-light, #818cf8);
}

/* ===== Mobile Drawer (hidden on desktop) ===== */
.dashboard-mobile-actions {
	display: none;
}

.dashboard-mobile-widget-bar {
	display: none;
}

.dashboard-mobile-drawer {
	display: none;
}

/* ===== Main Layout ===== */
.dashboard-main {
	display: flex;
	flex: 1;
	overflow: hidden;
	gap: 10px;
	/* Top gap is intentionally tighter than the sides: banner already carries
	   an 8px bottom margin (clearance for the collapsed state's hanging pills),
	   so 8px here reads as one ~16px gap instead of the old 20px band. */
	padding: 8px 16px 0 16px;
}

/* ===== Sidebar ===== */
.dashboard-sidebar {
	/* Width is user-draggable (side layout): the render applies the persisted
	   value as an inline --db-sidebar-w on this element, the stylesheet
	   default below keeps hand-built DOM and pre-feature data at 220. The
	   variable is UNITLESS so one value drives both the width (× 1px) and the
	   proportional content scale (÷ 220, see .dashboard-sidebar-widgets) with
	   no twin to keep in sync. The collapsed state overrides the width with a
	   literal 15px (source order wins). */
	--db-sidebar-w: 220;
	width: calc(var(--db-sidebar-w, 220) * 1px);
	flex-shrink: 0;
	display: flex;
	flex-direction: column;
	position: relative;
	transition: width 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.25s ease;
}

/* While a resize drag is live: kill the width/max-height transitions (the
   rail's 0.4s spring would lag every pointer frame) and stop text selection
   from painting across the board. Added/removed by the drag handlers. */
.dashboard-sidebar--resizing {
	transition: none !important;
	user-select: none;
}

/* Side-layout width drag handle: a slim col-resize strip riding the sidebar's
   right edge. INSIDE the box (right: 0, not -5px): the expanded state is
   overflow-y: auto, which computes overflow-x to auto too and would clip a
   negative offset. As a direct sidebar child it is auto-hidden in the
   collapsed state by the `> *:not(.slim-indicator)` rule, so the 15px rail
   stays click-to-expand. */
.dashboard-sidebar-width-handle {
	position: absolute;
	top: 0;
	bottom: 0;
	right: 0;
	width: 8px;
	cursor: col-resize;
	z-index: 6;
	touch-action: none;
}

.dashboard-sidebar-width-handle::before {
	content: '';
	position: absolute;
	top: 50%;
	/* Flush with the sidebar's right edge (into the widgets-area's 4px dead
	   zone), NOT further in: the cards' right borders sit 4px from the edge
	   (padding 0 4px on .dashboard-sidebar-widgets), so a 2px offset landed
	   the pill ON TOP of them. At right:0 the pill clears the border band and
	   reads as the pane divider. It cannot go past the edge — the expanded
	   sidebar's overflow-y:auto computes overflow-x to auto, which clips
	   anything beyond the padding box. */
	right: 0;
	transform: translateY(-50%);
	width: 3px;
	height: 40px;
	border-radius: 2px;
	background: var(--db-text-faint);
	opacity: 0;
	transition: opacity 0.2s ease, background 0.2s ease;
	pointer-events: none;
}

.dashboard-sidebar-width-handle:hover::before,
.dashboard-sidebar--resizing .dashboard-sidebar-width-handle::before {
	opacity: 0.65;
	background: var(--db-accent, var(--interactive-accent));
}

@media (max-width: 640px) {
	.dashboard-sidebar-width-handle {
		display: none;
	}
}

.dashboard-sidebar-scroll {
	flex: 1;
	overflow-y: auto;
	scrollbar-width: none;
	display: flex;
	flex-direction: column;
	gap: 10px;
	padding-top: 0;
}

.dashboard-sidebar-scroll::-webkit-scrollbar {
	width: 0;
}

/* ===== Sidebar Widgets ===== */
.dashboard-sidebar-widgets {
	display: flex;
	flex-direction: column;
	gap: 6px;
	padding: 0 4px;
}

/* Proportional content scaling (side layout): widget internals are em-based,
   so tying the area's root font-size to the dragged sidebar width scales
   every card's type together — 220 (the default width) is exactly the 1.0
   baseline, so the stock render is pixel-identical. The clamp keeps the
   smallest labels (0.65em tiers) legible at the 180 floor and stops
   headlines ballooning at the 420 ceiling. Fixed-px internals (book covers,
   the pomodoro ring, paddings) deliberately stay put — only type breathes.
   The stacked strip ignores this: its columns are a fixed 240px and the
   ratio input (--db-sidebar-w) only moves in the side layout. */
.dashboard-sidebar-widgets[data-layout="side"] {
	font-size: calc(1em * clamp(0.92, var(--db-sidebar-w, 220) / 220, 1.12));
}

.dashboard-sidebar-widget {
	background: var(--db-bg-card);
	border: 1px solid var(--db-border-card);
	border-radius: var(--db-radius-md);
	padding: 12px;
	backdrop-filter: var(--db-backdrop-blur);
	-webkit-backdrop-filter: var(--db-backdrop-blur);
	cursor: grab;
}

.dashboard-sidebar-widget--dragging {
	opacity: 0.4;
}

.dashboard-sidebar-widget--drag-over-top {
	border-top: 2px solid var(--db-accent) !important;
}

.dashboard-sidebar-widget--drag-over-bottom {
	border-bottom: 2px solid var(--db-accent) !important;
}

/* Single-button toolbar dropdown (view switcher / card size): pill shows the
 * current selection (icon or letter) plus a tiny caret hinting the menu. */
.dashboard-toolbar-dropdown {
	display: inline-flex;
	align-items: center;
	gap: 2px;
}

.dashboard-toolbar-dropdown {
	/* Both dropdown flavors share one box: the icon glyphs render 16px tall
	   (setIcon default), so the button gets that fixed content height — the
	   S/M/L letter button then matches the view button's size exactly. */
	min-height: 16px;
}

.dashboard-toolbar-dropdown-text {
	font-size: 0.82em;
	font-weight: 700;
	height: 16px;
	line-height: 16px;
	min-width: 16px;
	text-align: center;
}

/* ===== Widget card backgrounds (per-widget decorative images) ===== */
/* The layer is absolutely positioned with z-index:-1 inside an isolation
   context on the card: it paints above the card's own background (which
   shows through the image's opacity) but below all content, without
   repositioning any child. ::before carries the image (blurred + over-scaled
   so the blur edge never bleeds visibly); ::after is the black dimming
   overlay that keeps text readable over busy photos. */
.dashboard-sidebar-widget--has-bg {
	isolation: isolate;
}

/* Foreground scheme: redirect the card's theme text tokens to the chosen
   color so text AND icons (accent-driven) flip together over the photo.
   Muted/faint derive from the same color so the hierarchy survives. */
.dashboard-sidebar-widget--has-bg.dashboard-sidebar-widget--fg-set {
	--db-text: var(--wbg-fg, var(--db-text));
	--db-text-muted: color-mix(in srgb, var(--wbg-fg, var(--db-text)) 72%, transparent);
	--db-text-faint: color-mix(in srgb, var(--wbg-fg, var(--db-text)) 50%, transparent);
	--db-accent: var(--wbg-fg, var(--db-accent));
	/* Re-anchor INHERITED text color on the card: descendants without their
	   own color rule (quick-action labels, titles) inherit the ancestor's
	   already-resolved color, which bypasses the token overrides above —
	   setting `color` here makes the flip reach them too. */
	color: var(--db-text);
}

.dashboard-widget-bg {
	position: absolute;
	inset: 0;
	z-index: -1;
	overflow: hidden;
	border-radius: inherit;
	pointer-events: none;
}

.dashboard-widget-bg::before {
	content: '';
	position: absolute;
	inset: 0;
	background-image: var(--wbg-image);
	background-size: cover;
	background-position: center;
	opacity: var(--wbg-opacity, 1);
	filter: blur(var(--wbg-blur, 0px));
	transform: scale(var(--wbg-scale, 1));
}

.dashboard-widget-bg::after {
	content: '';
	position: absolute;
	inset: 0;
	background: rgb(0 0 0 / var(--wbg-dim, 0));
}

/* Glass inner frame on background-image cards (not the quick-actions card —
   its buttons already wear that treatment). The pane must read as a SEPARATE
   sheet of glass PRESSED ONTO the photo ("glass is glass, image is image"),
   not a tint fused with it, so unlike the buttons it carries:
   - its own frost (blur+saturate) instead of the theme's button blur (mostly
     none) — the photo visibly refracts under the pane;
   - a substantial fill: the theme's CARD surface token (much more present
     than the ~6% button tint), softened to 65% so the photo still shows;
   - a lit top edge + soft drop shadow — the classic glass-sheet highlight.
   Theme tokens keep every theme adapted; the phone CSS block disables
   backdrop-filter wholesale, where this degrades to the tinted fill. */
.dashboard-widget-frame {
	position: absolute;
	inset: 6px;
	z-index: -1;
	pointer-events: none;
	border-radius: calc(var(--db-radius-md, 10px) - 4px);
	background: color-mix(in srgb, var(--db-bg-card, rgba(127, 127, 127, 0.25)) 65%, transparent);
	border: 1px solid color-mix(in srgb, var(--db-accent, var(--interactive-accent)) 28%, transparent);
	box-shadow:
		inset 0 1px 0 rgba(255, 255, 255, 0.16),
		0 2px 10px rgba(0, 0, 0, 0.14);
	backdrop-filter: blur(7px) saturate(1.15);
	-webkit-backdrop-filter: blur(7px) saturate(1.15);
}

/* Half-hidden gear button at a card's top-right corner (the countdown
   settings-button recipe): invisible at rest, faint on card hover, full on
   its own hover. */
.dashboard-sidebar-widget--cfg,
.dashboard-sidebar-widget--has-bg {
	position: relative;
}

.dashboard-widget-cfg-btn {
	position: absolute;
	top: 8px;
	right: 8px;
	z-index: 2;
	visibility: hidden;
	background: none !important;
	border: none !important;
	box-shadow: none !important;
	color: var(--db-text-muted);
	width: 20px;
	height: 20px;
	box-sizing: border-box;
	padding: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	cursor: pointer;
	opacity: 0;
	transition: opacity 0.15s ease, color 0.15s ease;
}

.dashboard-sidebar-widget:hover .dashboard-widget-cfg-btn {
	visibility: visible;
	opacity: 0.5;
}

.dashboard-sidebar-widget:hover .dashboard-widget-cfg-btn:hover {
	opacity: 1;
	color: var(--db-accent);
}

.dashboard-widget-cfg-btn svg {
	width: 13px;
	height: 13px;
}

.dashboard-sidebar-anniversary .dashboard-widget-cfg-btn {
	visibility: visible;
	opacity: 1;
	width: var(--nand-control-height);
	height: var(--nand-control-height);
}

@media (pointer: coarse) {
	.dashboard-sidebar-anniversary .dashboard-widget-cfg-btn {
		width: var(--nand-touch-target);
		height: var(--nand-touch-target);
	}
}

/* ===== Unified widget header buttons =====
 * Every icon button on a widget card's top-right — the per-widget header
 * buttons (habit/music/expense/pomodoro stats, quick-actions palette/add)
 * plus the config gears — shares one size (20x20 box, 13px glyph) and one
 * visibility scheme: hidden at rest, half-lit on card hover, full accent on
 * its own hover. Card-scoped (not layout-scoped): both layouts behave the
 * same. Specificity beats each widget's own rules; the QA !important chrome
 * resets are untouched (they only cover background/border/shadow). */
.dashboard-sidebar-widget .dashboard-sidebar-habit-icon-btn,
.dashboard-sidebar-widget .dashboard-sidebar-music-icon-btn,
.dashboard-sidebar-widget .dashboard-sidebar-expense-icon-btn,
.dashboard-sidebar-widget .dashboard-sidebar-pomodoro-stats-btn,
.dashboard-sidebar-widget .dashboard-widget-inline-cfg-btn,
.dashboard-quick-actions .dashboard-qa-btn-group button {
	width: 20px;
	height: 20px;
	box-sizing: border-box;
	padding: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	opacity: 0;
	color: var(--db-text-muted);
	transition: opacity 0.15s ease, color 0.15s ease;
}

.dashboard-sidebar-widget .dashboard-sidebar-habit-icon-btn svg,
.dashboard-sidebar-widget .dashboard-sidebar-music-icon-btn svg,
.dashboard-sidebar-widget .dashboard-sidebar-expense-icon-btn svg,
.dashboard-sidebar-widget .dashboard-sidebar-pomodoro-stats-btn svg,
.dashboard-sidebar-widget .dashboard-widget-inline-cfg-btn svg,
.dashboard-quick-actions .dashboard-qa-btn-group button svg {
	width: 13px;
	height: 13px;
}

.dashboard-sidebar-widget:hover .dashboard-sidebar-habit-icon-btn,
.dashboard-sidebar-widget:hover .dashboard-sidebar-music-icon-btn,
.dashboard-sidebar-widget:hover .dashboard-sidebar-expense-icon-btn,
.dashboard-sidebar-widget:hover .dashboard-sidebar-pomodoro-stats-btn,
.dashboard-sidebar-widget:hover .dashboard-widget-inline-cfg-btn,
.dashboard-quick-actions:hover .dashboard-qa-btn-group button {
	opacity: 0.5;
}

.dashboard-sidebar-widget .dashboard-sidebar-habit-icon-btn:hover,
.dashboard-sidebar-widget .dashboard-sidebar-music-icon-btn:hover,
.dashboard-sidebar-widget .dashboard-sidebar-expense-icon-btn:hover,
.dashboard-sidebar-widget .dashboard-sidebar-pomodoro-stats-btn:hover,
.dashboard-sidebar-widget .dashboard-widget-inline-cfg-btn:hover,
.dashboard-quick-actions .dashboard-qa-btn-group button:hover {
	opacity: 1;
	color: var(--db-accent);
}

/* Habit card exception: its header keeps buttons ALWAYS visible — the left
   title + list leave the top-right corner empty otherwise. Covers the icon
   buttons AND the background-settings gear that joins their cluster. */
.dashboard-sidebar-habit .dashboard-sidebar-habit-icon-btn,
.dashboard-sidebar-habit .dashboard-widget-inline-cfg-btn {
	opacity: 0.55;
}

/* Inline gear that joins a header row's existing icon-button cluster (habit,
   music, quick actions) instead of a corner button that would overlap them.
   Ghost at rest like its siblings, accent on hover. */
.dashboard-widget-inline-cfg-btn {
	width: 20px;
	height: 20px;
	flex-shrink: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	cursor: pointer;
	color: var(--db-text-muted);
	opacity: 0.55;
	transition: opacity 0.15s ease, color 0.15s ease;
}

.dashboard-widget-inline-cfg-btn:hover {
	opacity: 1;
	color: var(--db-accent);
}

.dashboard-widget-inline-cfg-btn svg {
	width: 13px;
	height: 13px;
}

@media (prefers-reduced-motion: reduce) {
	.dashboard-quick-actions .dashboard-qa-btn-group button { transition: none; }
}

/* ===== Stacked layout (desktop/tablet only) ===== */
/* Top-bottom board: widget strip under the banner, sections below. Guarded by
   the exact inverse of the phone block's @media (max-width: 640px) so the two
   ranges are disjoint and phone CSS keeps winning by construction. Phones
   render data-layout="side" anyway (isStackedLayout excludes them). Not a
   container query on purpose: laying containment on the root would affect its
   position:fixed descendants (.dashboard-scroll-top); narrow desktop PANES are
   fine — the strip scrolls horizontally at any pane width and the board adapts
   via its own container query. (At viewport widths <=640px the phone treatment
   takes over instead: the sidebar is hidden and widgets live in the mobile
   bar.) */
@media (min-width: 641px) {
	/* Column board: widget strip on top, sections below. */
	[data-layout="stacked"] .dashboard-main {
		flex-direction: column;
	}

	/* The quick-notes work bar (hoisted out of the kanban by view.ts) rides
	   above the widget strip. Its base flex-basis 100% means WIDTH inside the
	   kanban's row layout but HEIGHT in this column layout — neutralize to
	   auto so the bar keeps its natural single-row height. */
	[data-layout="stacked"] .dashboard-main > .dashboard-quicknote {
		flex: 0 0 auto;
	}

	/* Shared scroll region: the quick-notes bar above stays pinned while the
	   widget deck AND the board scroll together through this one viewport.
	   Thin auto-hiding scrollbar, same recipe as the sections. */
	[data-layout="stacked"] .dashboard-scroll-region {
		flex: 1;
		min-height: 0;
		display: flex;
		flex-direction: column;
		gap: 10px;
		overflow-y: auto;
		scrollbar-width: thin;
		scrollbar-color: transparent transparent;
	}
	[data-layout="stacked"] .dashboard-scroll-region:hover {
		scrollbar-color: color-mix(in srgb, var(--db-accent, var(--interactive-accent)) 18%, transparent) transparent;
	}

	/* The sidebar stops being a fixed-width hover rail and becomes a full-width
	   strip host INSIDE the scroll region: natural height (the deck's grid
	   caps itself), no internal scrolling. The rail state classes keep strip
	   semantics: collapsed = slim horizontal bar, pinned = always open. The
	   generous max-height cap exists so the collapse animation has a numeric
	   start value (none->16px cannot interpolate). */
	[data-layout="stacked"] .dashboard-sidebar {
		width: auto;
		flex-shrink: 0;
		max-height: 2000px;
		overflow: hidden;
		transition: max-height 0.3s cubic-bezier(0.34, 1.2, 0.64, 1), opacity 0.25s ease;
		/* Widget strip unit height (the 6-row grid unit). Declared HERE, not on
		   the strip row: a custom property declared on the row itself would
		   shadow the value the drag handle / render writes inline on the
		   sidebar, and the row's grid-template-rows reads it through
		   inheritance. The renderer (view.applySidebarSizing) and the strip
		   height drag both write this same property on this same element.
		   Below ~300px the calendar card grows an internal scrollbar (cards
		   scroll internally by design); the drag floor is 240px. */
		--db-widget-unit-h: 300px;
	}

	[data-layout="stacked"] .dashboard-sidebar-scroll {
		overflow: visible;
		padding: 0;
	}

	/* Strip height drag handle: a centered pill riding the strip's bottom
	   edge. INSIDE the sidebar box (bottom: 0, not -5px) because the stacked
	   sidebar is overflow: hidden — a negative offset would be clipped. As a
	   direct sidebar child it is auto-hidden in the collapsed state by the
	   rail's `> *:not(.slim-indicator)` rule. The 72px center zone overlaps a
	   sliver of the strip's hover scrollbar — an accepted trade for keeping
	   the grip out of the cards' click area. */
	[data-layout="stacked"] .dashboard-sidebar-strip-handle {
		position: absolute;
		left: 50%;
		transform: translateX(-50%);
		bottom: 0;
		width: 72px;
		height: 10px;
		cursor: ns-resize;
		z-index: 6;
		touch-action: none;
	}

	[data-layout="stacked"] .dashboard-sidebar-strip-handle::before {
		content: '';
		position: absolute;
		left: 50%;
		bottom: 2px;
		transform: translateX(-50%);
		width: 40px;
		height: 3px;
		border-radius: 2px;
		background: var(--db-text-faint);
		opacity: 0.45;
		transition: opacity 0.2s ease, background 0.2s ease;
	}

	[data-layout="stacked"] .dashboard-sidebar-strip-handle:hover::before {
		opacity: 0.95;
		background: var(--db-accent, var(--interactive-accent));
	}

	/* The board unrolls to natural height inside the region — the kanban's
	   own scroller (base rule) is neutralized; sections keep their per-type
	   max-heights and internal card scrolling. */
	[data-layout="stacked"] .dashboard-kanban-wrapper {
		overflow: visible;
	}

	[data-layout="stacked"] .dashboard-kanban {
		overflow: visible;
		flex: 0 0 auto;
	}

	/* Collapsed strip: slim bar mirroring the rail's 15px sliver. The rail's
	   child-hiding rule (> *:not(slim-indicator)) applies unchanged. */
	[data-layout="stacked"] .dashboard-sidebar--collapsed {
		max-height: 16px;
		cursor: pointer;
		overflow: hidden;
	}

	/* Slim indicator becomes a horizontal pill on the strip. */
	[data-layout="stacked"] .dashboard-sidebar--collapsed .dashboard-sidebar-slim-indicator {
		width: 40px;
		height: 4px;
	}

	/* Stacked mode hides the week-calendar row and the recent-docs block. */
	[data-layout="stacked"] .dashboard-sidebar-week-calendar,
	[data-layout="stacked"] .dashboard-recent {
		display: none;
	}

	/* Quick actions as the pinned leftmost card in the strip grid: neutralize
	   the base fixed 180px height (the grid span owns sizing) and lay the
	   buttons out VERTICALLY (single column). It exits the reorder system in
	   stacked mode (renderer skips its DnD wiring), hence the default cursor. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="quickActions"] {
		grid-row: span 6;
		height: auto;
		cursor: default;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-quick-actions .dashboard-qa-list {
		grid-template-columns: repeat(2, 1fr);
	}

	/* The widget deck (built by renderSidebarWidgets in stacked mode): a
	   6-row grid flowing COLUMN-MAJOR. Height ratios are exact fractions of
	   one unit: full = 6 rows, two-thirds = 4, half = 3, third = 2 — 4+2,
	   3+3 and 2+2+2 all tile one column exactly. Columns are a fixed width
	   so cards stay uniform at any window size; overflow columns scroll
	   horizontally. Row heights derive from the unit so the fractions never
	   drift: 6 rows of calc((unit-h - 5*gap) / 6). Cards scroll internally
	   when their content outgrows the fraction (habit lists, music panel).

	   Per-type rules key off [data-widget-key], NOT the widget class: the
	   in-place data-widget refresh (view.refreshDataWidget) re-mounts
	   lunar/pomodoro/reading inside a bare wrapper that inherits the key, so
	   class-keyed child selectors would silently lose their span after a
	   refresh and collapse the card to one row.

	   TIERED cards (habit / reading / album-*) read their span from the
	   inline --db-widget-span variable the renderer writes after adaptive
	   column packing ("preferred tier, downshift to exactly fill a column
	   when it would otherwise misfit" — see src/widget-span.ts). The fallback
	   in each var() is the card's historical default tier, so a missing
	   variable reproduces the pre-feature layout. FIXED cards keep the
	   hardcoded spans below, mirrored by STACKED_FIXED_SPANS in
	   src/widget-span.ts — update both together. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row {
		--db-widget-unit: 240px;
		display: grid;
		grid-auto-flow: column;
		grid-auto-columns: var(--db-widget-unit);
		/* --db-widget-unit-h is declared on the stacked sidebar (see the
		   comment there): the drag handle and render write it inline on the
		   sidebar and the row inherits it. The 300px fallback covers a missing
		   variable (e.g. hand-built DOM in tests). */
		grid-template-rows: repeat(6, calc((var(--db-widget-unit-h, 300px) - 30px) / 6));
		grid-row-gap: 6px;
		grid-column-gap: 6px;
		overflow-x: auto;
		overflow-y: hidden;
		/* Scrollbar mirrors the .dashboard-section-cards / quicknote-nav
		   recipe: standard props on Chromium 121+ render the slim native pill
		   and neutralize theme-level ::-webkit-scrollbar hijacks. Invisible at
		   rest, accent-tinted on hover — the strip stays quiet until aimed at. */
		scrollbar-width: thin;
		scrollbar-color: transparent transparent;
	}
	[data-layout="stacked"] .dashboard-sidebar-widgets-row:hover {
		scrollbar-color: color-mix(in srgb, var(--db-accent) 18%, transparent) transparent;
	}
	[data-layout="stacked"] .dashboard-sidebar-widgets-row::-webkit-scrollbar {
		width: 0;
		height: 4px;
	}
	[data-layout="stacked"] .dashboard-sidebar-widgets-row::-webkit-scrollbar-track {
		background: transparent;
	}
	[data-layout="stacked"] .dashboard-sidebar-widgets-row::-webkit-scrollbar-thumb {
		background: transparent;
		border-radius: 3px;
		transition: background 0.2s ease;
	}
	[data-layout="stacked"] .dashboard-sidebar-widgets-row:hover::-webkit-scrollbar-thumb {
		background: color-mix(in srgb, var(--db-accent) 18%, transparent);
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key] {
		box-sizing: border-box;
		grid-row: span 6;
		overflow-y: auto;
		overflow-x: hidden;
		/* Fully invisible card scrollbar (hover/wheel still scrolls): the
		   standard property both hides the bar and frees its gutter on
		   Chromium 121+, and — the reason this beats a ::-webkit override —
		   neutralizes theme-level scrollbar hijacks (the project recipe, see
		   the quicknote bar). Inner scrollers (reading scroll) already hide
		   their own. */
		scrollbar-width: none;
	}

	/* Descendant (not child) so a refresh mount's inner widget keeps the
	   tightened padding and fills the mount's grid slot. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-widget {
		padding: 10px;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row > .dashboard-sidebar-widget-mount > .dashboard-sidebar-widget {
		height: 100%;
		box-sizing: border-box;
	}

	/* Two-thirds height: pairs with a third below to tile one column. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="weather"] {
		grid-row: span 4;
	}

	/* Tiered: the renderer writes the packed span inline; the fallback is the
	   historical default tier (two-thirds pairs with a third to tile a column). */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="habit"] {
		grid-row: span var(--db-widget-span, 4);
	}

	/* Half height: two stack to fill one column. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="pomodoro"],
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="expense"],
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="music"] {
		grid-row: span 3;
	}

	/* Tiered: fallback = the historical half-height default. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="reading"] {
		grid-row: span var(--db-widget-span, 3);
	}

	/* Third height: three stack to fill one column. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="lunar"],
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key^="countdown-"],
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="yearProgress"],
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key^="anniversary-"] {
		grid-row: span 2;
	}

	/* Album cards take their span from the per-instance --db-widget-span
	   (set inline by the renderer from each entry's heightRatio, carried onto
	   the refresh mount by refreshDataWidget). Inside the fixed-height card
	   the frame fills the body instead of keeping its aspect-ratio box, so
	   smaller fractions crop the photos (layers are object-fit: cover)
	   rather than overflowing. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key^="album-"] {
		grid-row: span var(--db-widget-span, 6);
		display: flex;
		flex-direction: column;
		overflow: hidden;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-album-body {
		flex: 1;
		min-height: 0;
		display: flex;
		flex-direction: column;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-album-frame,
	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-album-placeholder {
		aspect-ratio: auto;
		flex: 1;
		min-height: 0;
	}

	/* The calendar defines the unit height but must never pay for it with an
	   internal scrollbar: its content flexes to fill the fixed card (nav and
	   weekday rows stay fixed, the month grid host takes the rest and only
	   scrolls if a theme inflates it past the card). */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > [data-widget-key="calendar"] {
		display: flex;
		flex-direction: column;
		overflow: hidden;
	}

	/* Pomodoro compacted for the half-height card (content was ~44px over):
	   smaller progress ring, tighter gaps and button padding. Side layout
	   keeps the roomy proportions. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro {
		gap: 2px;
		/* Center the cluster vertically: the compact content leaves slack and
		   top-anchoring read head-heavy with a dead band at the bottom. */
		justify-content: center;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro-ring-wrap {
		width: 62px;
		height: 62px;
	}

	/* Size the svg through the wrap (attribute width=72 would otherwise win
	   in engines that drop the class) and keep it fully inside. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro-ring-wrap svg {
		width: 100%;
		height: 100%;
		display: block;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro-time {
		font-size: 0.95em;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro-dots {
		bottom: 7px;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-pomodoro-main-btn {
		padding: 1px 14px 0;
		font-size: 0.7em;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-widget.dashboard-sidebar-pomodoro {
		padding-top: 8px;
		padding-bottom: 4px;
	}

	/* Expense compacted for the half-height card: tighter paddings/gaps and
	   slightly smaller form text/buttons so a titled card with entries fits
	   without an internal scrollbar. Side layout keeps the roomy spacing. */
	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-expense-top {
		margin-bottom: 4px;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-expense-form {
		gap: 4px;
		font-size: 0.92em;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-widget.dashboard-sidebar-expense {
		padding-top: 8px;
		padding-bottom: 6px;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-sidebar-expense-row-main {
		gap: 4px;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row [data-widget-key="calendar"] > .dashboard-calendar-content,
	[data-layout="stacked"] .dashboard-sidebar-widgets-row > .dashboard-sidebar-calendar > .dashboard-calendar-content {
		flex: 1;
		min-height: 0;
	}

	[data-layout="stacked"] .dashboard-sidebar-widgets-row .dashboard-calendar-host {
		flex: 1;
		min-height: 0;
		overflow-y: auto;
	}
}

/* Habit Widget */
.dashboard-sidebar-habit-top {
	display: flex;
	align-items: center;
	flex-wrap: wrap;
	gap: 4px 6px;
	width: 100%;
	min-height: 20px;
