}

.dashboard-sidebar-habit-title {
	display: flex;
	align-items: center;
	gap: 6px;
	font-size: 0.7em;
	font-weight: 600;
	letter-spacing: 0.08em;
	color: var(--db-accent);
	user-select: none;
	white-space: nowrap;
	flex: 1;
	min-width: max-content;
}

.dashboard-sidebar-habit-title-text {
	flex-shrink: 0;
}

/* Tools use their own row so check-in counts never truncate the title. */
.dashboard-sidebar-habit-tools {
	display: flex;
	align-items: center;
	gap: 6px;
	flex-basis: 100%;
}

.dashboard-sidebar-habit-title-icon {
	display: flex;
	align-items: center;
	flex-shrink: 0;
	opacity: 0.85;
}

.dashboard-sidebar-habit-title-icon svg {
	width: 12px;
	height: 12px;
}

.dashboard-sidebar-habit-count {
	font-size: 0.65em;
	color: var(--db-text-muted);
	font-variant-numeric: tabular-nums;
	user-select: none;
}

.dashboard-sidebar-habit-top-spacer {
	flex: 1;
}

.dashboard-sidebar-habit-icon-btn {
	width: 20px;
	height: 20px;
	display: flex;
	align-items: center;
	justify-content: center;
	cursor: pointer;
	border-radius: var(--db-radius-sm);
	opacity: 0.3;
	color: var(--db-text-muted);
	transition: opacity var(--nand-duration) var(--nand-ease), background-color var(--nand-duration) var(--nand-ease);
	flex-shrink: 0;
}

.dashboard-sidebar-habit-icon-btn:hover {
	opacity: 0.75;
	background: var(--db-bg-hover);
}

.dashboard-sidebar-habit-list {
	display: flex;
	flex-direction: column;
	gap: 2px;
}

.dashboard-sidebar-habit-item {
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 4px 6px;
	border-radius: var(--db-radius-sm);
	cursor: pointer;
	transition: background-color var(--nand-duration) var(--nand-ease);
}

.dashboard-sidebar-habit-item:focus-visible {
	outline: 2px solid var(--db-accent);
	outline-offset: -2px;
}

.dashboard-sidebar-habit-item:hover {
	background: var(--db-bg-hover);
}

/* Keep a photo foreground paired with an opaque theme surface on hover. */
.dashboard-sidebar-widget--has-bg .dashboard-sidebar-habit-item:hover {
	--db-text: var(--db-control-text);
	--db-text-muted: var(--db-control-text);
	--db-accent: var(--db-control-text);
	background: var(--db-control-bg);
}

.dashboard-sidebar-habit-check {
	width: 16px;
	height: 16px;
	border: 1.5px solid var(--db-text-muted);
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	transition: border-color var(--nand-duration) var(--nand-ease), background-color var(--nand-duration) var(--nand-ease);
}

.dashboard-sidebar-habit-item:hover .dashboard-sidebar-habit-check:not(.dashboard-sidebar-habit-check--done) {
	border-color: var(--db-accent);
}

.dashboard-sidebar-habit-check--done {
	background: var(--db-accent);
