}

.dashboard-sidebar-widgets .dashboard-qa-header {
	min-height: 20px;
	margin: 0 0 8px 0;
	padding-bottom: 4px;
}

/* Compact widget title: smaller than the stock section title. */
.dashboard-sidebar-widgets .dashboard-qa-header .dashboard-section-title {
	font-size: 0.72em;
