/* Preserve a readable theme surface/text pair beneath decorative photos. */
.dashboard-sidebar-widgets .dashboard-sidebar-widget--has-bg .dashboard-qa-item {
	--db-text: var(--db-control-text);
	--db-text-muted: var(--db-control-text);
	--db-accent: var(--db-control-text);
	background: var(--qa-btn-bg, var(--db-control-bg));
	color: var(--db-control-text);
