	grid-template-columns: repeat(7, 1fr);
	gap: 2px;
	text-align: center;
}

.dashboard-task-reminder-calendar-header {
	font-size: 0.6875em;
	color: var(--db-text-muted, var(--text-faint));
	padding: 4px 0;
