.nand-contacts-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 272px), 1fr)); gap: var(--size-4-3); }
.nand-contacts-columns-5 { max-width: 1424px; margin-inline: auto; }
.nand-contacts-columns-6 { max-width: 1712px; margin-inline: auto; }
.nand-contacts-grid button.nand-contacts-card { display: flex; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: var(--size-4-3); width: 100%; height: 100%; min-height: 176px; padding: var(--size-4-4); color: var(--text-normal); font-size: var(--nand-text-body); font-weight: 400; text-align: start; white-space: normal; overflow-wrap: anywhere; transition: border-color var(--nand-duration) var(--nand-ease), box-shadow var(--nand-duration) var(--nand-ease), transform var(--nand-duration) var(--nand-ease); }
