/* Header: toolbar, filter row and the local-only notice. */
.nand-automation-header { display: flex; flex-direction: column; gap: var(--size-4-3); min-width: 0; }
.nand-automation-toolbar { gap: var(--size-4-2); }
.nand-automation-filters { display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--size-4-3); min-width: 0; }
.nand-automation-filter { flex: 1 1 160px; max-width: 100%; }
