.nand-automation-notice.is-off { background: color-mix(in srgb, var(--nand-tone-warning) 10%, transparent); color: var(--text-normal); }
.nand-automation-notice-icon { display: flex; flex: none; padding-top: 1px; color: var(--text-faint); }
.nand-automation-notice.is-off .nand-automation-notice-icon { color: var(--nand-tone-warning); }
.nand-automation-notice-icon svg { width: 14px; height: 14px; }

/* Master/detail layout. */
.nand-automation-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(240px, 32%) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); gap: var(--size-4-4); }
.nand-automation-list { min-height: 0; padding: var(--size-4-1); border-radius: var(--nand-radius-md); background: var(--nand-surface-muted); }
.nand-automation-list > button.nand-automation-item { flex-shrink: 0; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title status" "badges badges" "next next"; align-items: center; gap: 6px var(--size-4-2); padding: 10px var(--size-4-3); overflow-wrap: anywhere; }
.nand-automation-list > button.nand-automation-item:hover:not(.is-active) { background: var(--nand-surface); }
.nand-automation-list > button.nand-automation-item.is-history .nand-ui-list-item-title { color: var(--text-muted); font-weight: 500; }
