.nand-automation-item-badges .nand-ui-dot { width: 6px; height: 6px; }
.nand-automation-meta-icon { display: flex; flex: none; color: var(--text-faint); }
.nand-automation-meta-icon svg { width: 13px; height: 13px; }
.nand-automation-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--size-4-2); margin: 0; padding: var(--size-4-8) var(--size-4-4); color: var(--text-muted); font-size: var(--nand-text-body); text-align: center; }
.nand-automation-empty-icon { display: flex; color: var(--text-faint); }
.nand-automation-empty-icon svg { width: 28px; height: 28px; }
.nand-automation-placeholder { display: flex; align-items: center; justify-content: center; min-height: 0; border: 1px dashed var(--nand-border-color); border-radius: var(--nand-radius-md); color: var(--text-faint); opacity: 0.6; }
