.nand-automation-detail-heading h3 { margin: 0; color: var(--text-normal); font-size: var(--font-ui-large); font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.nand-automation-detail-actions { justify-content: flex-end; }
.nand-automation-view button.nand-automation-btn-danger:hover:not(:disabled) { background: color-mix(in srgb, var(--nand-tone-error) 12%, transparent); color: var(--nand-tone-error); }
