.nand-automation-detail-card .nand-ui-section-label { margin: var(--size-4-1) 0 0; }
.nand-automation-prompt { margin: 0; padding: var(--size-4-3); border: var(--nand-border); border-radius: var(--nand-radius-sm); background: var(--nand-surface-muted); color: var(--text-normal); font-family: var(--font-monospace); font-size: var(--nand-text-body); line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; }

/* History: a timeline of run cards. */
.nand-automation-section-head { display: flex; align-items: center; gap: var(--size-4-2); margin-top: var(--size-4-2); }
.nand-automation-section-head h4 { margin: 0; color: var(--text-normal); font-size: var(--nand-text-title); font-weight: 600; }
.nand-automation-count { font-variant-numeric: tabular-nums; }
.nand-automation-timeline { position: relative; display: flex; flex-direction: column; gap: var(--size-4-2); margin: 0; padding: 0 0 var(--size-4-2); list-style: none; }
.nand-automation-timeline::before { content: ""; position: absolute; top: var(--size-4-2); bottom: var(--size-4-2); left: 5px; width: 2px; border-radius: var(--nand-radius-pill); background: var(--nand-border-color); }
.nand-automation-run { position: relative; display: grid; grid-template-columns: 12px minmax(0, 1fr); gap: var(--size-4-3); margin: 0; padding: 0; }
.nand-automation-run-marker { position: relative; z-index: 1; width: 12px; height: 12px; margin-top: 14px; box-sizing: border-box; border: 2px solid var(--background-primary); border-radius: 50%; background: var(--text-faint); }
.nand-automation-run.is-success .nand-automation-run-marker { background: var(--nand-tone-success); }
.nand-automation-run.is-error .nand-automation-run-marker { background: var(--nand-tone-error); }
.nand-automation-run.is-warning .nand-automation-run-marker { background: var(--nand-tone-warning); }
.nand-automation-run.is-info .nand-automation-run-marker { background: var(--nand-tone-info); }
.nand-automation-run-card { display: flex; flex-direction: column; gap: var(--size-4-2); min-width: 0; padding: 10px var(--size-4-3); border: var(--nand-border); border-radius: var(--nand-radius-md); background: var(--nand-surface); transition: border-color var(--nand-duration) var(--nand-ease); }
.nand-automation-run-card:hover { border-color: var(--nand-border-color-strong); }
.nand-automation-run-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--size-4-2); min-width: 0; }
.nand-automation-run-time { color: var(--text-normal); font-size: var(--nand-text-body); font-weight: 500; font-variant-numeric: tabular-nums; }
.nand-automation-run-head button.nand-ui-btn { min-height: var(--nand-control-height-sm); padding: 0 var(--size-4-2); font-size: var(--nand-text-caption); }
.nand-automation-run-message { margin: 0; color: var(--text-normal); font-size: var(--nand-text-body); line-height: 1.5; overflow-wrap: anywhere; }
.nand-automation-run.is-error .nand-automation-run-message { color: var(--text-error); }
.nand-automation-run-usage { margin: 0; color: var(--text-muted); font-size: var(--nand-text-caption); font-variant-numeric: tabular-nums; }
.nand-automation-output { border-radius: var(--nand-radius-sm); background: var(--nand-surface-muted); }
.nand-automation-output > summary { display: flex; align-items: center; gap: 6px; min-height: 28px; padding: 0 var(--size-4-2); border-radius: var(--nand-radius-sm); color: var(--text-muted); font-size: var(--nand-text-caption); font-weight: 500; cursor: pointer; list-style: none; user-select: none; }
