.nand-automation-editor .setting-item-control :is(input, select, textarea) { min-width: 0; max-width: 100%; min-height: var(--nand-control-height); border-radius: var(--nand-radius-sm); }
.nand-automation-editor-body { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: var(--size-4-4); align-items: start; }
