.nand-automation-editor textarea { box-sizing: border-box; width: 100%; min-height: 240px; padding: var(--size-4-3); border-radius: var(--nand-radius-sm); font-family: var(--font-monospace); font-size: var(--nand-text-body); line-height: 1.55; resize: vertical; }
