.nand-automation-editor-side .setting-item-heading { padding: var(--size-4-4) 0 0; }
.nand-automation-editor-footer { border-top: var(--nand-border); padding-top: var(--size-4-3); }
.nand-automation-editor-footer .setting-item-control { gap: var(--size-4-2); }

@media (max-width: 700px) {
 .nand-automation-editor-body { grid-template-columns: minmax(0, 1fr); }
 .nand-automation-view button, .nand-automation-editor button { min-height: 44px; }
 .nand-automation-view .nand-automation-filter :is(input, select) { min-height: 44px; }
}
@media (pointer: coarse) {
 .nand-automation-view button, .nand-automation-view .nand-automation-output > summary, .nand-automation-editor button { min-height: var(--nand-touch-target); }
