}
@media (prefers-reduced-motion: reduce) {
 .nand-automation-run-card, .nand-automation-output-chevron { transition: none; }
}
@container nand-automation (max-width: 700px) {
 .nand-automation-layout { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); }
