.nand-sync-group-header h3 { margin: 0; font-size: var(--nand-text-body); font-weight: 600; }
.nand-sync-count { padding: 0 var(--nand-space-2); border-radius: var(--nand-radius-pill); background: var(--nand-surface-muted); color: var(--text-muted); font-size: var(--nand-text-caption); }
