.nand-sync-commits button.nand-sync-commit-row { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; width: 100%; height: auto; padding: var(--nand-space-2); border: 0; border-radius: var(--nand-radius-sm); background: none; box-shadow: none; text-align: start; cursor: pointer; }
