.nand-browser-address-wrap input.nand-browser-address:focus,
.nand-browser-address-wrap input.nand-browser-address:focus-visible { outline: none; box-shadow: none; }
.nand-browser-suggestions { position: absolute; z-index: 5; top: calc(100% + 4px); left: 0; right: 0; border: var(--nand-border); background: var(--nand-surface); border-radius: var(--nand-radius-sm); box-shadow: var(--nand-shadow-lg); overflow: hidden; }
.nand-browser-suggestions:empty { display: none; }
.nand-browser-suggestions button { display: flex; flex-direction: column; align-items: start; width: 100%; height: auto; padding: var(--size-4-2); text-align: left; }
