.nand-browser-suggestions small { color: var(--text-muted); }
.nand-browser-zoom { max-width: 80px; font-variant-numeric: tabular-nums; }
.nand-browser-viewport { position: relative; flex: 1; min-height: 0; overflow: hidden; }
.nand-browser-guest, .nand-browser-webview { width: 100%; height: 100%; }
.nand-browser-webview { display: flex; }
.nand-browser-empty { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--size-4-3); padding: var(--size-4-6); background: var(--nand-surface); color: var(--text-muted); text-align: center; }
.nand-browser-empty > svg { width: 32px; height: 32px; }
.nand-browser-empty p { max-width: 520px; overflow-wrap: anywhere; }
.nand-browser-loading { position: absolute; bottom: 0; left: 0; max-width: 100%; padding: var(--size-4-1) var(--size-4-2); color: var(--text-muted); background: var(--nand-surface-muted); font-size: var(--nand-text-caption); pointer-events: none; }
.nand-browser-find, .nand-browser-hint, .nand-browser-downloads { padding: var(--size-4-2); border-bottom: var(--nand-border); }
.nand-browser-find input { flex: 1; min-width: 0; }
