.nand-browser-modal .modal-content { margin: 0; height: 100%; min-height: 0; }
.nand-browser-modal .modal-title, .nand-browser-modal .modal-close-button { display: none; }
.nand-browser-overlay { position: absolute; inset: 0; z-index: 6; padding: var(--size-4-3); background: var(--nand-surface); overflow: auto; }
.nand-browser-grab { display: flex; flex-direction: column; gap: var(--size-4-3); }
