.nand-browser-grab pre { flex: 1; min-height: 80px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; margin: 0; background: var(--nand-surface-muted); border-radius: var(--nand-radius-sm); padding: var(--size-4-3); font-size: var(--nand-text-caption); }
.nand-browser-markup { display: flex; flex-direction: column; gap: var(--size-4-3); }
.nand-browser-markup-tools { flex-wrap: wrap; }
.nand-browser-markup-tools .is-active { background: var(--nand-accent-soft); color: var(--text-accent); }
.nand-browser-markup-canvas { min-height: 0; flex: 1; overflow: auto; }
.nand-browser-markup-canvas canvas { display: block; max-width: 100%; touch-action: none; cursor: crosshair; }
.nand-browser-shortcut { display: flex; align-items: center; gap: var(--size-4-1); }
.nand-browser-shortcut-open { flex: 1; min-width: 0; justify-content: start; text-align: left; }
.nand-browser-shortcut-open span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (max-width: 600px) {
	.nand-browser-toolbar { flex-wrap: wrap; }
	.nand-browser-address-wrap { order: -1; flex-basis: 100%; }
	.nand-browser-grab .nand-ui-toolbar { flex-wrap: wrap; }
}

/* Shared persistence feedback. */
.nand-save-status { display: flex; gap: var(--size-4-2); align-items: center; font-size: var(--font-smallest); color: var(--text-muted); padding: var(--size-2-2) var(--size-4-2); }
.nand-save-status--unsaved, .nand-save-status--conflict { color: var(--text-warning); flex-wrap: wrap; }
.dashboard-sidebar-widget > .nand-save-status { position: relative; z-index: 1; background: var(--background-primary); border-radius: var(--nand-radius-sm); }
.nand-save-status button { font-size: inherit; }
.nand-save-status button:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: 2px; }

.dashboard-qa-run { display: flex; align-items: center; gap: var(--size-4-2); flex: 1; min-width: 0; height: auto; padding: 0; border: 0; background: transparent; box-shadow: none; color: inherit; text-align: start; }
.dashboard-qa-run:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: 3px; }
.is-mobile .dashboard-qa-run { min-height: 44px; }

.terminal-context-panel { padding: var(--size-4-2); border-bottom: 1px solid var(--background-modifier-border); max-height: 35%; overflow: auto; }
.terminal-context-panel summary { cursor: pointer; padding: var(--size-4-1); }
.terminal-context-panel small { overflow-wrap: anywhere; color: var(--text-muted); }

.dashboard-sidebar-slim-indicator { padding: 0; border: 0; box-shadow: none; }
.dashboard-sidebar--collapsed .dashboard-sidebar-slim-indicator { pointer-events: auto; }
.dashboard-sidebar-slim-indicator:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: 3px; }
@media (max-width: 641px), (pointer: coarse) {
 .dashboard-mobile-drawer-content .dashboard-qa-run, .dashboard-mobile-drawer-content .dashboard-qa-add-btn { min-height: 44px; }
 .dashboard-mobile-drawer-content .dashboard-qa-name { max-width: none; white-space: normal; }
 .dashboard-mobile-drawer-content .dashboard-qa-add-btn > span { display: none; }
}

.dashboard-sidebar-widgets .dashboard-qa-item--saved { grid-column: 1 / -1; }
.dashboard-qa-item--saved .dashboard-qa-run { display: grid; grid-template-columns: auto minmax(0, 1fr); row-gap: var(--size-2-1); }
.dashboard-qa-item--saved .dashboard-qa-run > span:not(.dashboard-qa-icon) { grid-column: 2; min-width: 0; white-space: normal; overflow-wrap: anywhere; }
.dashboard-qa-item--saved .nand-ui-badge { justify-self: start; max-width: 100%; }

.nand-dashboard-root .dashboard-qa-item > button.dashboard-qa-run { background: transparent; box-shadow: none; }
.dashboard-qa-item--saved .dashboard-qa-icon { grid-column: 1; grid-row: 1 / 3; }


/* Host boundary and legacy embedded pages; removed as module pages migrate. */
.workspace-leaf-content[data-type="nand-workbench-view"] > .view-content { padding: 0; overflow: hidden; }
body:not(.is-mobile) .workspace-leaf-content[data-type="nand-workbench-view"] > .view-header { display: none; }
.nand-workbench-page[hidden], .nand-workbench-context[hidden], .nand-workbench-context-page[hidden] { display: none; }
.nand-workbench-context:empty { display: none; }
.nand-workbench-agent-objects { height: 100%; box-sizing: border-box; gap: var(--size-4-2); }
.nand-workbench-agent-objects:empty { display: none; }
.nand-automation-run-history { padding: var(--size-4-4); height: 100%; }
.nand-automation-run.is-selected { background: var(--nand-accent-soft); border-radius: var(--nand-radius-sm); }
.nand-automation-run:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: 2px; }

.nand-workbench-home-overview { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: var(--size-4-4); padding: var(--size-4-4); }
.nand-workbench-home-calendar, .nand-workbench-home-recent { min-width: 0; border: 1px solid var(--db-border); border-radius: var(--db-radius-md); padding: var(--size-4-3); }
.nand-workbench-home-recent .dashboard-recent { margin: 0; }
/* Stacked layout hides these classes in the sidebar. The home overview is the place they stay visible. */
.nand-workbench-home-overview .nand-workbench-home-calendar .dashboard-sidebar-week-calendar { display: flex; }
.nand-workbench-home-overview .nand-workbench-home-recent .dashboard-recent { display: block; }
@container (max-width: 560px) { .nand-workbench-home-overview { grid-template-columns: 1fr; } }
.nand-skills-widget {
	padding: var(--nand-space-3);
	overflow: auto;
	min-width: 0;
}

.nand-dashboard-root .dashboard-context-skill {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	min-width: var(--nand-control-height);
	min-height: var(--nand-control-height);
	color: var(--db-text-muted);
	border-radius: var(--db-radius-sm);
}

.dashboard-context-skill:focus-visible {
	outline: var(--nand-focus-ring);
}

.dashboard-context-skill svg {
	width: 16px;
	height: 16px;
}

/* Obsidian's app chrome disables text selection; context actions need the card's own text. */
.dashboard-card-body {
	user-select: text;
}

.nand-skills-widget .nand-ui-toolbar,
.nand-skills-row {
	display: flex;
	align-items: center;
	gap: var(--nand-space-2);
	flex-wrap: wrap;
}

.nand-skills-row > button:first-child {
	flex: 1;
	white-space: normal;
	overflow-wrap: anywhere;
}

.nand-skills-widget input:not([type='checkbox']),
.nand-skills-widget select,
.nand-skills-widget textarea,
.nand-skills-preview select {
	width: 100%;
	min-width: 0;
}

.nand-skills-editor {
	border-top: var(--nand-border);
	padding-top: var(--nand-space-3);
}

.nand-skill-picker {
	overflow-wrap: anywhere;
}

.nand-skills-choice {
	display: grid;
	gap: var(--nand-space-1);
	overflow-wrap: anywhere;
}

.nand-skills-choice small {
	color: var(--db-text-muted);
}

.nand-skills-check {
	display: flex;
	align-items: center;
	gap: var(--nand-space-2);
	min-height: var(--nand-control-height);
	overflow-wrap: anywhere;
}

.nand-skill-preview-dialog {
	width: min(760px, 95vw);
}

.nand-skills-preview fieldset {
	border: var(--nand-border);
	border-radius: var(--nand-radius-sm);
	min-width: 0;
	max-height: 200px;
	overflow: auto;
}

.nand-skills-widget button,
.nand-skills-preview button,
.nand-skills-widget select,
.nand-skills-preview select {
	min-height: var(--nand-control-height);
}

@media (pointer: coarse) {
	.nand-dashboard-root .dashboard-context-skill {
		min-width: var(--nand-touch-target);
		min-height: var(--nand-touch-target);
	}

	.nand-skills-widget button,
	.nand-skills-preview button,
	.nand-skills-check,
	.nand-skills-widget select,
	.nand-skills-preview select {
		min-height: var(--nand-touch-target);
	}

	.nand-skills-widget button,
	.nand-skills-preview button {
		min-width: var(--nand-touch-target);
	}
}
.nand-pipeline-host {
	min-width: 0;
	min-height: 0;
	overflow: auto;
	padding: var(--nand-space-3);
}

.nand-pipeline,
.nand-pipeline-config {
	min-width: 0;
	overflow-wrap: anywhere;
}

.nand-pipeline-config {
	max-width: 760px;
}

.nand-pipeline-config fieldset {
	min-width: 0;
	border: var(--nand-border);
	border-radius: var(--nand-radius-md);
	padding: var(--nand-space-3);
}

.nand-pipeline-filters,
.nand-pipeline .nand-ui-toolbar {
	display: flex;
	flex-wrap: wrap;
	align-items: end;
	gap: var(--nand-space-2);
}

.nand-pipeline-stages {
	display: flex;
	align-items: flex-start;
	gap: var(--nand-space-3);
	min-width: 0;
	overflow-x: auto;
	padding-bottom: var(--nand-space-2);
}

.nand-pipeline-stage {
	flex: 0 0 var(--nand-pipeline-width, 280px);
	min-width: 0;
	padding: var(--nand-space-2);
	background: var(--nand-surface-muted);
	border-radius: var(--nand-radius-md);
}

.nand-pipeline-card,
.nand-pipeline-new-note {
	padding: var(--nand-space-3);
	border: var(--nand-border);
	border-radius: var(--nand-radius-md);
	background: var(--nand-surface);
	min-width: 0;
	user-select: text;
}

.nand-pipeline-card > button:first-child {
	font-weight: 600;
	white-space: normal;
}

.nand-pipeline-card small,
.nand-pipeline-stage > header small {
	color: var(--text-muted);
}

.nand-pipeline-host input:not([type='checkbox']),
.nand-pipeline-host select,
.nand-pipeline-host textarea {
	min-width: 0;
	max-width: 100%;
}

.nand-pipeline-host button,
.nand-pipeline-host select,
.nand-pipeline-host input:not([type='checkbox']),
.nand-pipeline-host summary {
	min-height: var(--nand-control-height);
}

.nand-pipeline-host :focus-visible {
	outline: var(--nand-focus-ring);
}

@media (pointer: coarse) {
	.nand-pipeline-host button,
	.nand-pipeline-host select,
	.nand-pipeline-host input:not([type='checkbox']),
	.nand-pipeline-host summary {
		min-height: var(--nand-touch-target);
	}
}
